select NAME,TYPE,LINE,POSITION,TEXT from USER_ERRORS where NAME in('RRL_STOCK_LOAD_THERMAL','RRL_STOCK_HU_LOAD_CORE','RRL_LOAD_THERMAL_FACT_GUARD')order by NAME,TYPE,SEQUENCE;
select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_LOAD_THERMAL','RRL_STOCK_HU_LOAD_CORE','RRL_LOAD_THERMAL_FACT_GUARD');
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-14-1160-loading-temperature';
